// docs/language-extensions.md, section 6.1: an L-bracket gusset profile
// with tangent fillets, extruded. Run with --enable sketch.

// [Bracket]
leg_a  = 40;   // [20:80]
leg_b  = 30;   // [20:80]
t      = 4;    // [2:8]
gusset = 18;   // [8:30]
r      = 3;    // [1:6]
width  = 12;

linear_extrude(height = width)
sketch(name = "gusset", $fn = 48) {
  o  = point([0, 0]);
  a  = point([leg_a, 0]);
  a2 = point([leg_a, t]);
  g1 = point([t + gusset, t]);      // gusset foot on the horizontal leg
  g2 = point([t, t + gusset]);      // gusset foot on the vertical leg
  b2 = point([t, leg_b]);
  b  = point([0, leg_b]);

  bottom = line(o, a);
  end_a  = line(a, a2);
  top_a  = line(a2, g1);
  hyp    = line(g1, g2);
  in_b   = line(g2, b2);
  end_b  = line(b2, b);
  back   = line(b, o);

  fix(o);
  horizontal(bottom); length(bottom, leg_a);
  vertical(end_a);    length(end_a, t);
  horizontal(top_a);
  vertical(in_b);
  horizontal(end_b);  length(end_b, t);
  vertical(back);     length(back, leg_b);
  distance(o, g1, t + gusset, along = "x");
  distance(o, g2, t + gusset, along = "y");

  fillet(g1, r);      // tangent arcs where the gusset meets each leg
  fillet(g2, r);
}

// docs/language-extensions.md, section 6.2: a slot with explicit tangent
// arcs, cut from a plate. Run with --enable sketch.
slot_len = 30;
slot_w   = 8;

linear_extrude(3)
difference() {
  square([50, 20], center = true);
  translate([-slot_len / 2, 0])
  sketch(name = "slot") {
    c1   = point([0, 0]);
    c2   = point([slot_len, 0]);
    axis = line(c1, c2, construction = true);
    top  = line([0, slot_w / 2], [slot_len, slot_w / 2]);
    bot  = line([slot_len, -slot_w / 2], [0, -slot_w / 2]);
    e1   = arc(c1, top.start, bot.end);   // left cap, counter-clockwise through 180°
    e2   = arc(c2, bot.start, top.end);   // right cap, counter-clockwise through 0°

    fix(c1);
    horizontal(axis); length(axis, slot_len);
    tangent(e1, top); tangent(e1, bot);
    tangent(e2, top); tangent(e2, bot);
    diameter(e1, slot_w); equal(e1, e2);

    // Handles print with their variable names, and a sub-handle is the
    // entity it names.
    echo(top, top.start, e1.center == c1, e2.start == bot.start);
  }
}

// The design's section 6.3 (a base plate under its child, with a fixing
// hole 6 mm beyond the child's +x edge, centred in y), with the child's
// extent read from anchors it declares rather than from its bounding box,
// which needs a render (stage 6).

// Any module producing a gear: a toothed disc that declares its centre
// and its outer edges as anchors.
module gear(teeth = 17, m = 1, thick = 5) {
  r = m * teeth / 2 + m;
  linear_extrude(thick)
    for (i = [0:teeth - 1]) rotate(i * 360 / teeth) {
      circle(r = r - 1.25 * m, $fn = 4 * teeth);
      translate([r - m, 0]) square([2 * m, m], center = true);
    }
  anchor("hub", [0, 0, 0], [0, 0, 1]);
  anchor("+x", [r, 0, 0], [1, 0, 0]);
  anchor("-x", [-r, 0, 0], [-1, 0, 0]);
  anchor("+y", [0, r, 0], [0, 1, 0]);
  anchor("-y", [0, -r, 0], [0, -1, 0]);
}

module plate_for(margin = 4, thick = 3, hole_d = 5) {
  a = child_anchors(0);
  lo = [a["-x"][0][0], a["-y"][0][1]];
  hi = [a["+x"][0][0], a["+y"][0][1]];
  cy = a.hub[0][1];
  echo(lo = lo, hi = hi, hole = [hi[0] + 6, cy]);
  difference() {
    translate([lo[0] - margin, lo[1] - margin, -thick])
      cube([hi[0] - lo[0] + 2 * margin + 12, hi[1] - lo[1] + 2 * margin, thick]);
    translate([hi[0] + 6, cy, -thick - 1])
      cylinder(d = hole_d, h = thick + 2, $fn = 32);
  }
  children(0);  // reuses the queried instance
}

plate_for() translate([10, 5, 0]) gear(teeth = 17);

// Sketch anchors (with --enable sketch): solved values as anchors. Every
// entity the body names is one (a line's is its midpoint and direction,
// an arc's or a circle's its centre), and anchor(name, entity) adds more.

// Holes drilled at a sketch's named points, wherever the solve put them.
module holes_at(names, d = 3) {
  a = child_anchors(0);
  echo(a);
  difference() {
    linear_extrude(4) children(0);
    for (k = names) translate(a[k][0] - [0, 0, 1]) cylinder(d = d, h = 6, $fn = 16);
  }
}

w = 30;
h = 20;
holes_at(["hole", "c2", "mid"])
  translate([10, 0])
  rotate(90)
  sketch(name = "plate") {
    o = point([0, 0]); b = point([25, 0]); c = point([25, 25]); d = point([0, 25]);
    l1 = line(o, b); l2 = line(b, c); l3 = line(c, d); l4 = line(d, o);
    c2 = point([20, 10]);
    fix(o); horizontal(l1); vertical(l2); horizontal(l3); vertical(l4);
    length(l1, w); length(l2, h);
    fix(c2);
    anchor("hole", c);
    anchor("mid", l3);
    anchor("free", [5, 5]);
    // An explicit anchor named like an entity replaces the entity's own.
    anchor("d", o);
  }

// A helper module whose body is a sketch adds to the sketch it is called
// from: its named entities are not the outer sketch's to export, but its
// anchor() statements are.
module tab(at) sketch() {
  t = point(at);
  fix(t);
  anchor("tab", t);
  anchor("tab corner", [at[0] + 1, at[1] + 1]);
}
module show() { echo(child_anchors()); children(); }
show() sketch(name = "with helper") {
  p = point([0, 0]); q = point([10, 0]); r = point([0, 10]);
  a = line(p, q); b = line(q, r); c = line(r, p);
  fix(p); fix(q); fix(r);
  tab([3, 3]);
  arcs = circle([20, 0], 2);
  fix(arcs.center);
}

// A sketch that fails gives an empty polygon and exports no solved
// anchors (its anchor() with coordinates stays).
show() sketch(name = "conflict") {
  p = point([0, 0]); q = point([10, 0]);
  l = line(p, q);
  fix(p); fix(q); length(l, 5);
  anchor("kept", [1, 1]);
}

// The design's section 6.3 as written: a base plate under its child, with
// a fixing hole 6 mm beyond the child's +x edge, centred in y, all read
// from the child's bounding box (`child_bounds()`, which renders it).
// `plate.scad` is the same model with the extent read from anchors.

// Any module producing a gear: a toothed disc, with no anchors.
module gear(teeth = 17, m = 1, thick = 5) {
  r = m * teeth / 2 + m;
  linear_extrude(thick)
    for (i = [0:teeth - 1]) rotate(i * 360 / teeth) {
      circle(r = r - 1.25 * m, $fn = 4 * teeth);
      translate([r - m, 0]) square([2 * m, m], center = true);
    }
}

module plate_for(margin = 4, thick = 3, hole_d = 5) {
  b  = child_bounds(0);                 // forces the child's geometry
  lo = b[0];
  hi = b[1];
  cy = (lo[1] + hi[1]) / 2;
  echo(lo = lo, hi = hi, hole = [hi[0] + 6, cy]);
  difference() {
    translate([lo[0] - margin, lo[1] - margin, -thick])
      cube([hi[0] - lo[0] + 2 * margin + 12, hi[1] - lo[1] + 2 * margin, thick]);
    translate([hi[0] + 6, cy, -thick - 1])
      cylinder(d = hole_d, h = thick + 2, $fn = 32);
  }
  children(0);                          // reuses the queried instance
}

plate_for() translate([10, 5, 0]) gear(teeth = 17);

// The measurements too: sums over the mesh, the same on wasm32.
module measure() { m = child_measure(0); echo(volume = m.volume, surface_area = m.surface_area); }
measure() gear(teeth = 17);

// Stage 7's queries on wasm32: child_bounds() through the fast path
// (a rotated union of primitives, found without the kernels) and through
// a render (a difference), and child_distance() between solids and in 2D.
module b() { echo(bounds = child_bounds(0)); children(0); }
module gap() { echo(gap = child_distance(0, 1)); children(); }
b() rotate([10, 20, 30]) union() { cube([1, 2, 3]); translate([4, 0, 0]) sphere(1.5, $fn = 12); }
b() difference() { cube(5); sphere(2); }
gap() { cube(1); translate([2, 2, 2]) cube(1); }
gap() { cube(10, center = true); sphere(2, $fn = 12); }
translate([20, 0, 0]) linear_extrude(1) gap() { square(4); translate([7, 4]) square(4); }
